local M = class("DoubleFestivalMainControl",LikeOO.OOControlBase)
function M:onEnter()
    M.super.onCreate(self)
    self:updateTime()
end

function M:onHandle(msg , data)
    if msg == 99999 then
        if self.m_model.m_is_token == true then
            self:updateMsg("refresh_data",nil,"TopUpGiftBag.ToKensSelectGiftBagPop")
        end
        self:closeView()
        --- 切换页签
    elseif type(msg) == "number" then
        self:switchTabBtn(msg)
    elseif msg == "btn_buySkinBtn" then
        self:buyForSDK(data.charge_id)
    elseif msg == "btn_buyGiftBtn" then
        if data.price <= 0 then
            self.m_model:getNetData("gift_value_daily_recv",data, function(response)
                if response then
                    if self:activityOverExamine(response) then
                        return
                    end
                    RewardUtil:rewardTipsByData(response.reward)
                    self:refreshChildView(true, false)
                end
            end, nil, nil, nil)
        else
            self:buyForSDK(data.charge_id)
        end
    elseif msg == "btn_gotShopTaskBtn" then
        self.m_model:getNetData("new_year_exchange", {vsn = data.version, gift_id = data.gift_id}, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                --cell_data.user_num = cell_data.user_num -  cell_data.data_num
                --cell_data.curExchangeCount = cell_data.curExchangeCount + 1
                RewardUtil:rewardTipsByData(response.reward)
                self:refreshChildView(false, false,{openId = data.openId, response = response})
                self.m_model:updateNetData(response)
            end
        end, nil, nil, nil)
    elseif msg == "btn_smashEggsBtn" then
        self.m_model:getNetData("new_year_egg", data, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                --self.m_model.m_serverData.daySmashCount = 1
                RewardUtil:rewardTipsByData(response.reward)
                self:refreshChildView(false, false, {openId = data.openId, response = response})
                self.m_model:updateNetData(response)
            end
        end, nil, nil, nil)
    elseif msg == "btn_gotEggBoxAwardBtn" then
        self.m_model:getNetData("new_year_egg_recv", {vsn = data.version}, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                --self:setObjectVisible("canGotAward_btn"..index, false)
                --self:setObjectVisible("got_btn"..index, true)
                RewardUtil:rewardTipsByData(response.reward)
                self:refreshChildView(false, false,{openId = data.openId, response = response})
                self.m_model:updateNetData(response)
            end
        end, nil, nil, nil)
    elseif msg == "btn_wishingTaskBtn" then
        local params = {vsn = data.version, quest_id = data.quest_id}
        self.m_model:getNetData("new_year_recv_quest", params, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                RewardUtil:rewardTipsByData(response.reward)
                --cell_data.status = 2
                --local luaBehaviour = UIUtil.findLuaBehaviour(cell_object)
                --LuaBehaviourUtil.setObjectVisible(luaBehaviour, "btn_getBtn", cell_data.status == 1)
                --LuaBehaviourUtil.setObjectVisible(luaBehaviour, "text_gotBtnText", cell_data.status == 2)
                --self.m_serverData.score = response.score
                self:refreshChildView(false, false, {openId = data.openId, response = response})
                self.m_model:updateNetData(response)
            end
        end, nil, nil, nil)
    elseif msg == "btn_shakeWishingBtn" then
        self.m_model:getNetData("new_year_tree_shake", { vsn = data.version }, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                --self.m_serverData.score = response.score
                RewardUtil:rewardTipsByData(response.reward)
                self:refreshChildView(false, false, {openId = data.openId, response = response})
                self.m_model:updateNetData(response)
            end
        end, nil, nil, nil)
    elseif msg == "btn_togglebtn_1" then
        self.m_view:switchTabUpdate(1)
    elseif msg == "btn_togglebtn_2" then
        self.m_view:switchTabUpdate(2)
    elseif msg == "btn_togglebtn_3" then
        self.m_view:switchTabUpdate(3)
    elseif msg == "btn_togglebtn_4" then
        self.m_view:switchTabUpdate(4)
    elseif msg == "btn_infoBtn" then
        local new_yearData = ConfigManager:getCfgByName("new_year")
        local versionData = new_yearData[self.m_model.m_version] or {}
        local content = versionData.des
        local mainData = self.m_model.m_activityXlsxData[self.m_model.m_mainOpenId] or {}
        local titleName = mainData.name or ""
        self:openView("Pops.CommonHelpPop", { title = titleName, content = content })
    elseif msg == "showSmashEggAniEvent" then
        -- 砸蛋的延时事件
        self:setOnceTimer(data.timer,function()
            self:updateMsg(data.msgName, data.params)
        end)
