function M:setShowTreeEnterEvent()
    -- 0读611的时间，1显示页签
    local openAstrictIndex = ConfigManager:getCommonValueById(610) or 0
    self.m_model:setIsShowTreeTab(true)
    if (openAstrictIndex == 0) then
        local curTimer = UserDataManager:getServerTime()
        local targetTimer = ConfigManager:getCommonValueById(611) or curTimer
        self.m_model:setIsShowTreeTab(curTimer >= targetTimer)
        if not self.m_model.m_isShowTree then
            self:setOnceTimer(math.ceil(targetTimer - curTimer),function()
                self.m_model:setIsShowTreeTab(true)
                ---置灰恢复
                self.m_view:refreshTab2Type()
            end)
        end
    end
end

-- 按钮切换
function M:switchTabBtn(index)
    if self.m_model.m_open_tab_index ~= index then
        self.m_model.m_open_tab_index = index
        self:refreshChildView(false, true, self.m_model.m_data, index) 
    end
end

-- 是否请求所有活动数据，是否删除节点重新加载，单个活动数据刷新的数据
function M:refreshChildView(isReqAllData, isDeleteViewNode, responseData, tab_index)
    if isReqAllData then
        --  1 砸金蛋, 2 许愿树,3 灵鹿集市, 4礼包屋
        self.m_model:getNetData("new_year_index", {index = 2}, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                self.m_model:refreshData(response)
                self.m_view:switchTabNode(isDeleteViewNode)
            end
        end, nil, nil, nil)
    else
        if not responseData then
            return
        end
        self.m_model:refreshItemActivityData(responseData, tab_index)
        self.m_view:switchTabNode(isDeleteViewNode)
    end
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView()
        return true
    end
    return false
end

--调用sdk充值
function M:buyForSDK(charge_id)
    if self.m_model.m_is_token == true then
        self:buyUseVoucher(charge_id, function ()
            self:setOnceTimer(0.5,function()
                -- 需要延时，sdk到服务器有一个延时
                self:refreshChildView(true, false)
            end)
        end)
        return
    end
    if self.timer_id then
        Logger.logWarningAlways(self.timer_id, "-------------IsPay-----------")
        return
    end
    self.m_view:lockTouch()
    self.timer_id = self:setOnceTimer(2, function ()
        self.m_view:unlockTouch()
        self.timer_id = nil
    end)
    PayUtil:rechargeByChargeId(charge_id, function ()
        if self.m_view then
            self.m_view:unlockTouch()
            if self.timer_id then
                self:removeTimer(self.timer_id)
                self.timer_id = nil
            end
            self:setOnceTimer(0.5,function()
                -- 需要延时，sdk到服务器有一个延时
                self:refreshChildView(true, false)
            end)
        end
    end)
end

--使用代金券购买
function M:buyUseVoucher(data, callback)
    local function receivetCallback(response)
        if callback then
            callback()
        end
        if response and response.reward then
            RewardUtil:rewardTipsByData(response.reward)
        end
    end
    local charge = ConfigManager:getCfgByName("charge")
    local cfg = charge[data]
    if cfg == nil then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0129",data), delay_close = 2})
        return
    end
    local voucher_data = RewardUtil:getProcessRewardData({RewardUtil.REWARD_TYPE_KEYS.VOUCHER,0,0})
    if voucher_data.user_num < cfg.price then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0130",data), delay_close = 2})
        return
    end
    local params = {
        charge_id = data
    }
    self.m_model:getNetData("voucher", params, receivetCallback)
end

function M:updateTime()
    local timerFormat, residueTimer = self.m_model:getDayTimer()
    if self.m_model.m_open_tab_index == 4 and self.m_view.m_cur_tab_node then
        self.m_view.m_cur_tab_node:refreshDayTimer(timerFormat)
    end
    self:setTimer(1,function()
        local timerFormat2, residueTimer2 = self.m_model:getDayTimer()
        if self.m_model.m_open_tab_index == 4 and self.m_view.m_cur_tab_node then
            self.m_view.m_cur_tab_node:refreshDayTimer(timerFormat2)
        end
    end)
end

function M:destroy()
    self:removeTimer(self.m_timer_id)
    M.super.destroy(self)
end

return M